<script setup lang="ts">
import type { Destination } from '../../types'
import StatusBadge from '../StatusBadge.vue'
defineProps<{ destinations: readonly Destination[] }>()
const emit = defineEmits<{ toggle: [destination: Destination, enabled: boolean]; test: [id: string]; rotate: [id: string]; finishRotation: [id: string]; remove: [id: string] }>()
</script>
<template><div class="cards"><article v-for="destination in destinations" :key="destination.id" class="destination-card"><div class="destination-main"><div class="destination-title"><h3>{{ destination.name }}</h3><StatusBadge :status="destination.enabled ? 'enabled' : 'disabled'" /></div><p>{{ destination.url }}</p><code>POST /v1/destinations/{{ destination.id }}/events</code><p class="signing">Standard Webhooks v1<span v-if="destination.has_previous_secret"> · rotation active</span></p></div><div class="actions"><button class="secondary" :disabled="!destination.enabled" @click="emit('test',destination.id)">Send test</button><button class="secondary" @click="emit('toggle',destination,!destination.enabled)">{{ destination.enabled ? 'Pause' : 'Resume' }}</button><button v-if="destination.has_previous_secret" class="secondary" @click="emit('finishRotation',destination.id)">Finish rotation</button><button class="secondary" @click="emit('rotate',destination.id)">Rotate secret</button><button class="danger" @click="emit('remove',destination.id)">Delete</button></div></article><p v-if="!destinations.length" class="empty panel">Create the first delivery destination.</p></div></template>
